-- 세트 110: Vault 입문: 비밀을 맡기는 금고
-- Vault 세트(docs/specs/spec_content_reinforcement.md). 정답·해설은 서버만 안다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (110, 1, 'Vault 상태 확인하기', 'Vault 서버가 열려 있는지(unseal), 초기화됐는지 보는 명령입니다. 빈칸을 채워 보세요.', '"상태"를 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["status", "login", "kv", "operator"]', NULL, '`vault status` 는 서버가 초기화됐는지(`Initialized`), 잠겨 있는지(`Sealed`)를 보여 줘요. Vault 를 만지기 전에 가장 먼저 습관처럼 치는 명령이에요.', '[0]', 'vault {0}', NULL, NULL),
  (110, 2, 'Vault 는 무엇일까?', 'Vault 를 가장 알맞게 설명한 것은 무엇일까요?', '비밀번호·토큰·인증서 같은 "비밀"을 맡아 두는 금고예요.', NULL, NULL, '[]', 'choice', '["서버를 감시하는 모니터링 도구", "컨테이너 이미지 저장소", "비밀번호·토큰·인증서 같은 비밀을 안전하게 저장하고, 누가 볼 수 있는지 통제하는 금고", "로그를 모으는 서비스"]', 2, '맞아요! Vault 는 비밀을 암호화해 저장하고 정책에 따라 꼭 필요한 사람·앱만 꺼내 쓰게 해 줘요.', NULL, NULL, NULL, NULL),
  (110, 3, 'Sealed 가 무슨 뜻일까?', '`vault status` 에 `Sealed  true` 가 보입니다. 무슨 뜻일까요?', 'Seal 은 "봉인"이에요. 금고 문이 잠겨 있다고 생각해 보세요.', NULL, NULL, '[]', 'choice', '["정상적으로 모든 기능이 열려 있다", "데이터가 암호화된 채 잠겨 있어, unseal(봉인 해제)을 해야 사용할 수 있다", "디스크가 가득 찼다", "비밀번호가 만료됐다"]', 1, '좋아요! 서버가 재시작되면 보통 Sealed 상태로 시작해요. 정해진 수의 unseal 키를 넣어야 금고가 열립니다.', NULL, NULL, NULL, NULL),
  (110, 4, '초기화와 열기 명령', 'Vault 를 처음 설치하면 ① **초기화**(unseal 키와 root 토큰 만들기)를 하고, ② 키를 넣어 **봉인을 해제**합니다. 빈칸을 채워 보세요.', '처음 만들 때는 init, 열 때는 unseal 이에요.', NULL, NULL, '[]', 'fill', '["init", "unseal", "raft", "seal"]', NULL, '`init` 은 딱 한 번 실행해 unseal 키 조각들과 root 토큰을 만들어 줍니다. 그 값은 다시 보여 주지 않으니 안전하게 나눠 보관해야 해요. `unseal` 은 키 조각을 하나씩 넣어 금고를 엽니다.', '[0, 1]', 'vault operator {0}
vault operator {1}', NULL, NULL),
  (110, 5, 'unseal 키를 나눠 갖는 이유', 'init 하면 unseal 키 조각이 5개 나오고, 그중 3개를 모아야 금고가 열립니다. 이렇게 나누는 이유는 무엇일까요?', '한 사람이 혼자 금고를 열 수 없게 만든 장치예요.', NULL, NULL, '[]', 'choice', '["키가 많을수록 더 빠르게 열리려고", "암호가 너무 길어서", "기록용으로", "한 사람이 혼자 금고를 열 수 없도록 여러 사람이 나눠 보관하게 하려고 (한 조각을 잃어도 괜찮게도 해 준다)"]', 3, '이 방식을 Shamir 비밀 분산이라고 해요. 5개 중 3개처럼 일부만 모여도 열려서, 몇 명이 자리에 없어도 운영할 수 있어요.', NULL, NULL, NULL, NULL),
  (110, 6, '처음 시작하는 순서', 'Vault 를 새로 설치한 뒤 사용하기까지의 흐름을 **앞에서 뒤**로 놓아 보세요.', '초기화 → 열기 → 로그인 → 사용 순서예요.', NULL, NULL, '[]', 'order', '["`vault login` 으로 root 토큰으로 접속해 정책과 인증 방식을 설정한다", "`vault operator init` 으로 초기화하고 unseal 키와 root 토큰을 받는다", "정해진 수의 키로 `vault operator unseal` 을 해서 봉인을 푼다", "앱·사용자용 정책과 토큰(또는 인증 방식)을 만들어 일상 업무에 쓴다"]', NULL, '**init → unseal → login(root) → 정책·인증 설정 → 일상 사용** 입니다. root 토큰은 최초 설정에만 쓰고, 이후엔 권한이 제한된 토큰으로 일하는 것이 안전해요.', '[1, 2, 0, 3]', NULL, NULL, NULL),
  (110, 7, 'root 토큰은 어떻게 다룰까?', 'init 때 받은 root 토큰은 모든 권한을 가집니다. 올바른 사용법은 무엇일까요?', '열쇠 중 가장 센 열쇠는 평소에 쓰지 않는 게 안전해요.', NULL, NULL, '[]', 'choice', '["모든 개발자에게 공유한다", "코드에 넣어 둔다", "최초 설정에만 쓰고, 평소엔 정책으로 권한을 제한한 토큰을 쓴다. root 토큰은 사용 후 폐기하거나 안전하게 보관한다", "메신저에 붙여 둔다"]', 2, '최소 권한 원칙이에요. root 토큰이 새면 금고 전체가 열린 것과 같으니, 평소엔 필요한 경로만 읽을 수 있는 토큰을 써요.', NULL, NULL, NULL, NULL),
  (110, 8, 'KV 에 비밀 넣고 꺼내기', '① 경로 `secret/app` 에 `password=s3cret` 을 **저장**하고, ② 그 경로의 값을 **읽는** 명령입니다. (예시 값입니다)', '넣을 때 put, 꺼낼 때 get 이에요.', NULL, NULL, '[]', 'fill', '["get", "put", "delete", "list"]', NULL, '`kv put` 으로 비밀을 저장하고 `kv get` 으로 읽어요. 코드나 git 에 비밀번호를 적는 대신 이렇게 Vault 에 두고 실행할 때 가져오면 훨씬 안전합니다.', '[1, 0]', 'vault kv {0} secret/app password=s3cret
vault kv {1} secret/app', NULL, NULL),
  (110, 9, '정책 한 줄 읽기', '앱이 `secret/data/app/*` 경로의 비밀을 **읽기만** 하게 허용하는 정책의 핵심 줄입니다. 빈칸을 채우세요.', '허용할 동작 이름은 영어로 "읽기"예요.', NULL, NULL, '[]', 'fill', '["read", "delete", "sudo", "root"]', NULL, '정책은 "어느 경로에 어떤 동작(capabilities)을 허용하나"를 적어요. 필요한 만큼만(`read`) 주는 것이 최소 권한 원칙이에요. `sudo` 같은 강한 권한은 신중히 주세요.', '[0]', 'path "secret/data/app/*"
capabilities = ["{0}"]', NULL, NULL),
  (110, 10, '토큰에 만료 시간을 두는 이유', 'Vault 토큰에는 만료 시간(TTL)을 두는 것이 좋습니다. 이유는 무엇일까요?', '유출됐을 때의 피해 기간을 짧게 해 줘요.', NULL, NULL, '[]', 'choice', '["토큰이 더 빨리 만들어진다", "토큰이 유출돼도 일정 시간이 지나면 저절로 쓸 수 없게 되어 피해 기간이 짧아진다", "디스크를 아낄 수 있다", "비밀이 자동으로 바뀐다"]', 1, '필요한 만큼만 쓰고, 오래 일하는 앱은 만료 전에 갱신(renew)해요. 만료 없는 토큰은 한 번 새면 계속 위험해요.', NULL, NULL, NULL, NULL),
  (110, 11, '앱이 비밀을 안전하게 쓰는 흐름', '앱이 Vault 의 비밀을 가져다 쓰는 안전한 흐름을 **앞에서 뒤**로 놓아 보세요.', '먼저 "나는 누구다"를 증명하고, 열쇠를 받고, 쓰고, 열쇠는 사라집니다.', NULL, NULL, '[]', 'order', '["받은 토큰으로 정책이 허용한 경로의 비밀을 읽는다", "앱이 인증 방식(AppRole, k8s 인증 등)으로 Vault 에 자신을 증명한다", "시간이 지나면 토큰이 만료되어 더 이상 쓸 수 없다", "짧은 TTL 의 토큰을 발급받는다"]', NULL, '**인증 → 짧은 토큰 발급 → 정책 범위 안에서 읽기 → 만료** 입니다. 앱 코드나 설정 파일에 비밀번호를 박아 두지 않아도 돼요.', '[1, 3, 0, 2]', NULL, NULL, NULL),
  (110, 12, '비밀을 코드에 넣으면 왜 위험할까?', '비밀번호를 소스 코드나 git 저장소에 그대로 적어 두면 어떤 문제가 생길까요?', 'git 은 지운 뒤에도 과거 기록이 남아요.', NULL, NULL, '[]', 'choice', '["아무 문제 없다", "빌드가 느려진다", "코드가 더 짧아진다", "저장소를 보는 모든 사람에게 노출되고, 지운 뒤에도 git 이력에 남아 있어 유출 사고로 이어질 수 있다"]', 3, '그래서 비밀은 Vault 같은 곳에 두고 실행할 때 가져오게 해요. 이미 올렸다면 지우는 것으로 끝나지 않고 그 비밀을 폐기·교체해야 합니다.', NULL, NULL, NULL, NULL);
